<template><view class="page"><view class="intro"><text>快速开卡</text><small>店员一次完成，不再拆成开卡、财务确认两次操作</small></view><view class="section"><text class="label">购卡客户</text><view class="select-row" @click="memberVisible=true"><view v-if="member.member_id"><strong>{{member.display_name}}</strong><small>{{member.mobile_masked}}</small></view><text v-else class="placeholder">按姓名或手机号选择客户</text><u-icon name="arrow-right" color="#94a3b8"/></view></view><view class="section"><text class="label">选择卡种</text><view class="products"><view v-for="p in products" :key="p.id" class="product" :class="{active:form.product_id===p.id}" @click="form.product_id=p.id"><view><strong>{{p.product_name}}</strong><small>{{p.item?.usage_mode==='unlimited'?'不限次':`${p.item?.total_times||0} 次`}} · {{p.validity_text}}</small></view><text>¥{{money(p.sale_price)}}</text></view><view v-if="!products.length" class="empty">暂无已启用卡种，请先在 PC 端配置</view></view></view><view class="section"><text class="label">收款处理</text><view class="mode-tabs"><view :class="{active:form.settlement_mode==='immediate'}" @click="form.settlement_mode='immediate'">现场收款</view><view v-if="config.allow_receivable===1" :class="{active:form.settlement_mode==='receivable'}" @click="form.settlement_mode='receivable'">记入应收</view></view><view v-if="form.settlement_mode==='immediate'" class="select-row account" @click="accountVisible=true"><view><strong>到账账户</strong><small>{{accountName||'请选择实际到账账户'}}</small></view><u-icon name="arrow-right" color="#94a3b8"/></view><ErpVoucherUploader v-if="form.settlement_mode==='immediate'" v-model="voucherUrls" title="收款凭证（选填）" hint="可上传转账截图，财务流水长期留痕"/></view><view class="section"><text class="label">备注</text><u-textarea v-model="form.remark" height="110rpx" maxlength="255" placeholder="选填，活动来源或特殊约定"/></view><view class="safe-bottom"></view><view class="bottom"><u-button type="primary" text="确认开卡" :loading="submitting" @click="submit"/></view><MemberCardMemberPopup v-model:show="memberVisible" @select="member=$event"/><u-popup :show="accountVisible" mode="bottom" :safe-area-inset-bottom="true" border-radius="28rpx" @close="accountVisible=false"><view class="account-sheet"><view class="sheet-head"><text>选择到账账户</text><u-icon name="close" @click="accountVisible=false"/></view><view v-for="a in config.capital_account_options||[]" :key="a.id" class="account-item" @click="selectAccount(a)"><text>{{a.name}}</text><u-icon v-if="form.capital_account_id===a.id" name="checkmark" color="#3b6ef5"/></view></view></u-popup></view></template>
<script setup lang="ts">import{computed,reactive,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{createCardOrder,getCardProductOptions,getMemberCardConfig,memberCardRequestId}from'../../api';import MemberCardMemberPopup from'../../components/MemberCardMemberPopup.vue';import ErpVoucherUploader from'@/addon/hsx_erp/components/ErpVoucherUploader.vue';const memberVisible=ref(false),accountVisible=ref(false),submitting=ref(false),products=ref<any[]>([]),config=ref<any>({allow_receivable:1,capital_account_options:[]}),member=ref<any>({}),voucherUrls=ref(''),form=reactive<any>({product_id:0,settlement_mode:'immediate',capital_account_id:0,remark:''});const money=(v:any)=>Number(v||0).toFixed(2),accountName=computed(()=>config.value.capital_account_options?.find((a:any)=>Number(a.id)===Number(form.capital_account_id))?.name||'');const selectAccount=(a:any)=>{form.capital_account_id=Number(a.id);accountVisible.value=false};const submit=async()=>{if(!member.value.member_id)return uni.showToast({title:'请选择购卡客户',icon:'none'});if(!form.product_id)return uni.showToast({title:'请选择卡种',icon:'none'});if(form.settlement_mode==='immediate'&&!form.capital_account_id)return uni.showToast({title:'请选择到账账户',icon:'none'});submitting.value=true;try{const r:any=(await createCardOrder({...form,member_id:member.value.member_id,request_id:memberCardRequestId('issue'),voucher_urls:voucherUrls.value?voucherUrls.value.split(',').filter(Boolean):[]}))?.data;uni.showToast({title:r.success?'开卡成功':'开卡单已保存',icon:r.success?'success':'none'});setTimeout(()=>uni.redirectTo({url:'/addon/hsx_member_card/pages/order/list'}),700)}finally{submitting.value=false}};onLoad(async()=>{const[p,c]:any=await Promise.all([getCardProductOptions(),getMemberCardConfig()]);products.value=p?.data||[];config.value=c?.data||config.value;form.capital_account_id=Number(config.value.default_capital_account_id||0)})</script>
<style scoped>.page{min-height:100vh;padding:24rpx 24rpx 150rpx;background:#f3f4f6;box-sizing:border-box}.intro{display:flex;margin-bottom:22rpx;flex-direction:column}.intro text{font-size:38rpx;font-weight:750}.intro small{margin-top:8rpx;color:#64748b;font-size:23rpx}.section{margin-bottom:20rpx;padding:24rpx;border:1rpx solid #e8edf4;border-radius:18rpx;background:#fff}.label{display:block;margin-bottom:17rpx;color:#0f172a;font-size:27rpx;font-weight:700}.select-row,.product,.sheet-head,.account-item{display:flex;align-items:center;justify-content:space-between;gap:18rpx}.select-row{min-height:86rpx;padding:0 18rpx;border:1rpx solid #e2e8f0;border-radius:13rpx}.select-row>view{display:flex;flex-direction:column;gap:5rpx}.select-row small,.product small{color:#64748b;font-size:21rpx}.placeholder{color:#94a3b8}.products{display:flex;flex-direction:column;gap:13rpx}.product{padding:22rpx;border:2rpx solid #edf1f6;border-radius:15rpx}.product.active{border-color:#3b6ef5;background:#eff6ff}.product>view{display:flex;flex-direction:column;gap:8rpx}.product>text{color:#ea580c;font-weight:750}.mode-tabs{display:grid;grid-template-columns:repeat(2,1fr);gap:10rpx}.mode-tabs view{padding:19rpx;border:1rpx solid #e2e8f0;border-radius:12rpx;text-align:center}.mode-tabs view.active{border-color:#3b6ef5;background:#eff6ff;color:#3b6ef5;font-weight:700}.account{margin:18rpx 0}.bottom{position:fixed;right:0;bottom:0;left:0;padding:18rpx 24rpx calc(18rpx + env(safe-area-inset-bottom));border-top:1rpx solid #e5e7eb;background:#fff;z-index:20}.account-sheet{padding:30rpx 26rpx}.sheet-head{padding-bottom:20rpx;font-size:31rpx;font-weight:700}.account-item{padding:25rpx 4rpx;border-top:1rpx solid #eef2f7}.empty{padding:35rpx;color:#94a3b8;text-align:center}</style>
